import json

L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]

L_set = set(L)
triples = []
n = len(L)
for i in range(n):
    a = L[i]
    for j in range(i+1, n):
        b = L[j]
        s = a + b
        if s in L_set and s != a and s != b:
            triples.append((a, b, s))

num_to_triples = {x: [] for x in L}
for idx, (a, b, c) in enumerate(triples):
    num_to_triples[a].append(idx)
    num_to_triples[b].append(idx)
    num_to_triples[c].append(idx)

used = set()
solution = []

def backtrack():
    if len(used) == n:
        return True
    min_n = None
    min_opts = None
    for num in L:
        if num in used:
            continue
        opts = [idx for idx in num_to_triples[num] if all(x not in used for x in triples[idx])]
        if not opts:
            return False
        if min_opts is None or len(opts) < len(min_opts):
            min_opts = opts
            min_n = num
            if len(min_opts) == 1:
                break
    for idx in min_opts:
        a, b, c = triples[idx]
        used.update([a, b, c])
        solution.append([a, b, c])
        if backtrack():
            return True
        used.difference_update([a, b, c])
        solution.pop()
    return False

found = backtrack()
witness = {'existence': found}
if found:
    witness['triples'] = solution
print(f'WITNESS: {json.dumps(witness, separators=(',', ':'))}')
